from taf.sbts.oam.coam.admin.utils import raise_value_error


class LTEUplink(object):
    def __init__(self, dist_name, reference_channel_number, reporting_time_interval, resource_block_offset,
                 earfcn, enable_harq, enable_digital_output, digital_output_type,
                 bit_rate, bb_selector, hst_config, resource_index_cqi, enable_dli_interference,
                 tdd_frame_conf, tdd_spec_subf_conf, nb_subcarrier_index, measured_frc,
                 reference_channel_number_nb_linked, local_cell_res_id_nb_linked,
                 inband_prb_index_ul, guardband_index_ul, nb_repetitions=None, nb_subframe_offset=None):

        self.dist_name = dist_name

        self.reference_channel_number = self.validate_param('referenceChannelNumber',
                                                            reference_channel_number,
                                                            (reference_channel_number in (
                                                                "Invalid", "A1_1", "A1_2",
                                                                "A1_3", "A1_4", "A1_5",
                                                                "A1_6", "A1_7", "A1_8",
                                                                "A1_9", "A2_1", "A2_2",
                                                                "A2_3", "A2_4", "A2_5",
                                                                "A3_1", "A3_2", "A3_3",
                                                                "A3_4", "A3_5", "A3_6",
                                                                "A3_7", "A4_1", "A4_2",
                                                                "A4_3", "A4_4", "A4_5",
                                                                "A4_6", "A4_7", "A4_8",
                                                                "A5_1", "A5_2", "A5_3",
                                                                "A5_4", "A5_5", "A5_6",
                                                                "A5_7", "A7_1", "A7_2",
                                                                "A7_3", "A7_4", "A7_5",
                                                                "A7_6", "A8_1", "A8_2",
                                                                "A8_3", "A8_4", "A8_5",
                                                                "A8_6", "A14_1", "A15_1",
                                                                "DCM_1", "DCM_2", "DCM_3",
                                                                "DCM_4", "DCM_5", "DCM_6",
                                                                "DCM_7", "DCM_8", "A16_2",
                                                                "A16_3", "A16_4", "A16_5",
                                                                "A17_1", "A17_2", "A17_3",
                                                                "A17_4", "A17_5", "A17_6"
                                                            ))
                                                            )

        self.reporting_time_interval = self.validate_param('reportingTimeInterval',
                                                           reporting_time_interval,
                                                           (1 <= reporting_time_interval <= 4294967295))

        self.resource_block_offset = self.validate_param('resourceBlockOffset',
                                                         resource_block_offset,
                                                         (0 <= resource_block_offset <= 99))

        self.earfcn = self.validate_param('earfcn',
                                          earfcn,
                                          (0 <= earfcn <= 262143))

        self.enable_harq = self.validate_param('enableHarq',
                                               enable_harq,
                                               (enable_harq is None or enable_harq in (True, False)))

        self.enable_digital_output = self.validate_param('enableDigitalOutput',
                                                         enable_digital_output,
                                                         (enable_digital_output is None
                                                          or enable_digital_output in (True, False)))

        self.digital_output_params = {"digitalOutputType": self.validate_param('digitalOutputType',
                                                                               digital_output_type,
                                                                               (digital_output_type in (
                                                                                   "BinaryHarq",
                                                                                   "SerialAgilent",
                                                                                   "SerialRs"
                                                                               ))),
                                      "bitRate": self.validate_param('bitRate',
                                                                     bit_rate,
                                                                     (bit_rate is None or bit_rate in
                                                                      ("115Dot2Kbps",
                                                                       "460Dot8Kbps",
                                                                       "1Dot92Mbps"
                                                                       ))),
                                      "bbSelector": self.validate_param('bbSelector',
                                                                        bb_selector,
                                                                        (bb_selector is None or bb_selector in
                                                                         ("00",
                                                                          "01",
                                                                          "10",
                                                                          "11"
                                                                          )))
                                      }

        self.hst_config = self.validate_param('hstConfig',
                                              hst_config,
                                              (hst_config is None or hst_config in (
                                                  "NotApplied", "HstScenario1", "HstScenario3",
                                                  "HstPucchScenario1", "HstPucchScenario3")))

        self.resource_index_cqi = self.validate_param('resourceIndexCqi',
                                                      resource_index_cqi,
                                                      (resource_index_cqi is None or (0 <= resource_index_cqi <= 1185)))

        self.enable_dli_interference = self.validate_param('enableDLInterference',
                                                           enable_dli_interference,
                                                           (enable_dli_interference is None
                                                            or enable_dli_interference in (True, False)))

        self.tdd_frame_conf = self.validate_param('tddFrameConf',
                                                  tdd_frame_conf,
                                                  (tdd_frame_conf is None or (1 <= tdd_frame_conf <= 3)))

        self.tdd_spec_subf_conf = self.validate_param('tddSpecSubfConf',
                                                      tdd_spec_subf_conf,
                                                      (tdd_spec_subf_conf is None or (3 <= tdd_spec_subf_conf <= 9)))

        self.nb_subcarrier_index = self.validate_param(
            'nbSubcarrierIndex',
            nb_subcarrier_index,
            (nb_subcarrier_index is None or (0 <= nb_subcarrier_index <= 47)))

        self.ul_test_model_nb_linked = {"measuredFrc": self.validate_param('measuredFrc',
                                                                           measured_frc,
                                                                           (measured_frc is None or measured_frc in
                                                                            ("nbLinked",
                                                                             "both"
                                                                             ))),

                                        "referenceChannelNumberNbLinked": self.validate_param(
                                            'referenceChannelNumberNbLinked',
                                            reference_channel_number_nb_linked,
                                            (reference_channel_number_nb_linked is None
                                             or reference_channel_number_nb_linked in
                                             ("A14_1",
                                              "A15_1",
                                              "A16_2",
                                              "A16_3",
                                              "A16_4",
                                              "A16_5"
                                              ))),

                                        "localCellResIdNbLinked": self.validate_param(
                                            'localCellResIdNbLinked',
                                            local_cell_res_id_nb_linked,
                                            (local_cell_res_id_nb_linked is None
                                             or (0 <= local_cell_res_id_nb_linked <= 4294967295))),

                                        "inbandPRBIndexUl": self.validate_param(
                                            'inbandPRBIndexUl',
                                            inband_prb_index_ul,
                                            (inband_prb_index_ul is None or (0 <= inband_prb_index_ul <= 99))),
                                        "guardbandIndexUl": self.validate_param(
                                            'guardbandIndexUl',
                                            guardband_index_ul,
                                            (guardband_index_ul is None
                                             or guardband_index_ul in
                                             ("undefined",
                                              "plus4590kHz",
                                              "plus6840kHz",
                                              "plus9090kHz",
                                              "minus4590kHz",
                                              "minus6840kHz",
                                              "minus9090kHz"
                                              ))),
                                        }

        self.nb_repetitions = self.validate_param('nbRepetitions', nb_repetitions,
                                                  (nb_repetitions is None
                                                   or nb_repetitions in ("NBR_1", "NBR_2", "NBR_16", "NBR_64")))

        self.nb_subframe_offset = self.validate_param('nbSubframeOffset', nb_subframe_offset,
                                                      (nb_subframe_offset is None
                                                       or (0 <= nb_subframe_offset <= 255)))

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_digital_output_param(parameter):
            return response_dict['params']['digitalOutputParams'][parameter]

        def _get_ul_test_model_nb_linked_param(parameter):
            return response_dict['params']['ulTestModelNbLinked'][parameter]

        def _get_optional_param(test_type, parameter):
            return response_dict['params'][test_type][parameter] \
                if parameter in response_dict['params'][test_type] else None

        params = response_dict['params']
        dist_name = response_dict['lncel_rDN']
        reference_channel_number = params['referenceChannelNumber']
        reporting_time_interval = params['reportingTimeInterval']
        resource_block_offset = params['resourceBlockOffset']
        earfcn = params['earfcn']
        enable_harq = params['enableHarq'] if 'enableHarq' in params else None
        enable_digital_output = params['enableDigitalOutput'] if 'enableDigitalOutput' in params else None

        digital_output_params = {"digitalOutputType": _get_digital_output_param('digitalOutputType'),
                                 "bitRate": _get_optional_param('digitalOutputParams', 'bitRate'),
                                 "bbSelector": _get_optional_param('digitalOutputParams', 'bbSelector')}

        hst_config = params['hstConfig'] if 'hstConfig' in params else None
        resource_index_cqi = params['resourceIndexCqi'] if 'resourceIndexCqi' in params else None
        enable_dli_interference = params['enableDLInterference'] if 'enableDLInterference' in params else None
        tdd_frame_conf = params['tddFrameConf'] if 'tddFrameConf' in params else None
        tdd_spec_subf_conf = params['tddSpecSubfConf'] if 'tddSpecSubfConf' in params else None
        nb_subcarrier_index = params['nbSubcarrierIndex'] if 'nbSubcarrierIndex' in params else None

        ul_test_model_nb_linked = {"measuredFrc": _get_optional_param('ulTestModelNbLinked', 'measuredFrc'),
                                   "referenceChannelNumberNbLinked": _get_optional_param(
                                       'ulTestModelNbLinked', 'referenceChannelNumberNbLinked'),
                                   "localCellResIdNbLinked": _get_optional_param(
                                       'ulTestModelNbLinked', 'localCellResIdNbLinked'),
                                   "inbandPRBIndexUl": _get_optional_param('ulTestModelNbLinked', 'inbandPRBIndexUl'),
                                   "guardbandIndexUl": _get_optional_param('ulTestModelNbLinked', 'guardbandIndexUl')
                                   }
        nb_repetitions = params['nbRepetitions'] if 'nbRepetitions' in params else None
        nb_subframe_offset = params['nbSubframeOffset'] if 'nbSubframeOffset' in params else None

        return cls(
            dist_name=dist_name,
            reference_channel_number=reference_channel_number,
            reporting_time_interval=reporting_time_interval,
            resource_block_offset=resource_block_offset,
            earfcn=earfcn,
            enable_harq=enable_harq,
            enable_digital_output=enable_digital_output,
            digital_output_type=digital_output_params["digitalOutputType"],
            bit_rate=digital_output_params["bitRate"],
            bb_selector=digital_output_params["bbSelector"],
            hst_config=hst_config,
            resource_index_cqi=resource_index_cqi,
            enable_dli_interference=enable_dli_interference,
            tdd_frame_conf=tdd_frame_conf,
            tdd_spec_subf_conf=tdd_spec_subf_conf,
            nb_subcarrier_index=nb_subcarrier_index,
            measured_frc=ul_test_model_nb_linked["measuredFrc"],
            reference_channel_number_nb_linked=ul_test_model_nb_linked["referenceChannelNumberNbLinked"],
            local_cell_res_id_nb_linked=ul_test_model_nb_linked["localCellResIdNbLinked"],
            inband_prb_index_ul=ul_test_model_nb_linked["inbandPRBIndexUl"],
            guardband_index_ul=ul_test_model_nb_linked["guardbandIndexUl"],
            nb_repetitions=nb_repetitions,
            nb_subframe_offset=nb_subframe_offset,
        )

    def as_dict(self):
        self.digital_output_params = self._remove_empty_params(self.digital_output_params)
        self.ul_test_model_nb_linked = self._remove_empty_params(self.ul_test_model_nb_linked)

        attributes = {'lncel_rDN': self.dist_name,
                      'params': {'referenceChannelNumber': self.reference_channel_number,
                                 'reportingTimeInterval': self.reporting_time_interval,
                                 'resourceBlockOffset': self.resource_block_offset,
                                 'earfcn': self.earfcn,
                                 'enableHarq': self.enable_harq,
                                 'enableDigitalOutput': self.enable_digital_output,
                                 'digitalOutputParams': self.digital_output_params,
                                 'hstConfig': self.hst_config,
                                 'resourceIndexCqi': self.resource_index_cqi,
                                 'enableDLInterference': self.enable_dli_interference,
                                 'tddFrameConf': self.tdd_frame_conf,
                                 'tddSpecSubfConf': self.tdd_spec_subf_conf,
                                 'nbSubcarrierIndex': self.nb_subcarrier_index,
                                 'nbRepetitions': self.nb_repetitions,
                                 'nbSubframeOffset': self.nb_subframe_offset,
                                 }
                      }

        if self.ul_test_model_nb_linked:
            attributes['params']['ulTestModelNbLinked'] = self.ul_test_model_nb_linked

        attributes['params'] = {k: v for k, v in attributes['params'].items() if v is not None}

        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-startLteUplinkTest.html")

    @staticmethod
    def _remove_empty_params(params):
        return {k: v for k, v in params.items() if v is not None}
